import sys

def check(n: int) -> bool:
    s = 0
    while n > 0:
        s += n % 10
        n //= 10
    return s == 10

def solution(reader, writer):
    data = reader.read().split()
    if not data:
        return
    k = int(data[0])
    i = 19
    while k > 0:
        if check(i):
            k -= 1
        if k == 0:
            writer.write(str(i) + "\n")
            return
        i += 1

def main():
    reader = sys.stdin.buffer
    writer = sys.stdout.buffer
    solution(reader, writer)

if __name__ == "__main__":
    main()

